M=[l.rstrip('\n').split('\t') for l in open(S+'/win7-map.tsv') if l.strip()]
groups={1:['WRD'],2:['CTL','LAY'],3:['MSG','FDB'],4:['KEY','PTR','A11Y'],5:['WIN','CMD'],6:['HLP','CON','OTH']}
topic2g={'wording':1,'controls':2,'layout':2,'messages':3,'feedback':3,'keyboard':4,'pointer':4,'accessibility':4,'windows-and-dialogs':5,'commands':5,'help':6,'consistency':6,'other':6}
pre2g={p:g for g,ps in groups.items() for p in ps}
rules={r['id']:r for r in d.RULES}
out={g:{'rules':[],'notes':[],'new':[]} for g in groups}
for r in d.RULES:
  g=pre2g[r['id'].split('-')[0]]
  rr=dict(r); rr['src']=['apple-'+s for s in r['src']]; rr['enf']=[list(e) for e in r['enf']]; rr['now']=list(r['now'])
  out[g]['rules'].append(rr)
for rid,mid,note in M:
  w=W[rid]
  rec={'id':rid,'rule':w['rule'],'quote':w['quote'],'platforms':w['platforms'],'topic':w['topic'],'checklist':w['in_windows_checklist'],'url':w['url']}
  if mid=='NEW':
    rec['title']=note; out[topic2g[w['topic']]]['new'].append(rec)
  elif note:
    rec['merged']=mid; rec['note']=note; out[pre2g[mid.split('-')[0]]]['notes'].append(rec)
for g,o in out.items():
  json.dump(o,open(S+f'/consol/in-{g}.json','w'),indent=0)
  print(g,groups[g],len(o['rules']),len(o['notes']),len(o['new']))
"; cp $S/kvit-ui-survey.md $S/consol/

